mod tests {
    use super::*;

    fn number(f: f64) -> String {
        let mut s = String::new();
        push_f64(&mut s, f);
        s
    }

    #[test]
    fn plain_value_is_not_escaped() {
        assert_eq!(escape_value("hello"), "hello");
    }

