    let input = signatures.map(|sig| {
        let mut b = block("a.ts", 1, 5, SymbolKind::Function, Vec::new());
        b.symbol_signature = Some(sig.to_string());
        (b, tokens(&["foo"]))
    });
    let df: HashMap<String, usize> = HashMap::from([("foo".to_string(), 2)]);
